#include <USB.h>
#include <USBHIDKeyboard.h>

USBHIDKeyboard Keyboard;

#define BTN_PIN 0    // кнопка BOOT
#define LED_PIN 48   // onboard RGB светодиод

// ---------- радуга ----------
unsigned long lastStep = 0;
int hue = 0;                 // 0..359 — угол по цветовому кругу

// HSV -> RGB (H в градусах, S и V в процентах)
void hsvToRgb(int h, int s, int v, int &r, int &g, int &b) {
  int region = (h / 60) % 6;          // 6 секторов цветового круга
  int frac = (h % 60) * 100 / 60;     // дробная часть сектора 0..99
  int p = v * (100 - s) / 100;
  int q = v * (100 - s * frac / 100) / 100;
  int t = v * (100 - s * (100 - frac) / 100) / 100;

  switch (region) {
    case 0: r = v; g = t; b = p; break;
    case 1: r = q; g = v; b = p; break;
    case 2: r = p; g = v; b = t; break;
    case 3: r = p; g = q; b = v; break;
    case 4: r = t; g = p; b = v; break;
    case 5: r = v; g = p; b = q; break;
  }
}

void rainbowStep() {
  if (millis() - lastStep < 15) return;   // скорость перелива (меньше = плавнее и быстрее)
  lastStep = millis();

  int r, g, b;
  hsvToRgb(hue, 100, 100, r, g, b);       // s=100, v=100 — чистый насыщенный цвет
  neopixelWrite(LED_PIN, r * 255 / 100, g * 255 / 100, b * 255 / 100);

  hue = (hue + 1) % 360;                  // шаг по кругу; увеличь для более быстрого перелива
}

// ---------- выключение ПК ----------
void shutdownPc() {
  Keyboard.press(KEY_LEFT_ALT);
  Keyboard.press(KEY_LEFT_SHIFT);
  delay(20);
  Keyboard.releaseAll();
  delay(60);

  Keyboard.press(KEY_LEFT_GUI);
  Keyboard.press('r');
  delay(40);
  Keyboard.releaseAll();
  delay(500);

  Keyboard.print("shutdown /s /t 5");
  delay(100);

  Keyboard.press(KEY_RETURN);
  delay(30);
  Keyboard.release(KEY_RETURN);
}

void setup() {
  Serial.begin(115200);

  pinMode(BTN_PIN, INPUT_PULLUP);

  USB.begin();
  Keyboard.begin();
  delay(2000);
  Serial.println("Ready");
}

void loop() {
  // кнопка проверяется неблокирующе, чтобы радуга не замирала
  if (digitalRead(BTN_PIN) == LOW) {
    neopixelWrite(LED_PIN, 255, 0, 0);    // красный — команда принята
    shutdownPc();
    delay(5000);                          // LED горит 5 секунд
    lastStep = millis();                  // радуга продолжится с чистого листа
  }
  rainbowStep();
  delay(2);
}
